  const pageOrders=useMemo(()=>sorted.slice((safePage-1)*pageSize,safePage*pageSize),[sorted,safePage,pageSize]);
  const data=useMemo<Order[]>(()=>grouped?statuses.map(s=>({id:"'`group-${s.id}`,status:s.id,children:pageOrders.filter(o=>o.status===s.id)} as Order)).filter(g=>g.children!.length):pageOrders,[pageOrders,grouped]);
  const onRowSelectionChange=useRowSelectionFixedHandler({rowSelection,setRowSelection,tableData:data,getSubRows,getRowId});
  const columns=useMemo<ColumnDef<Order>[]>(()=>[
    {id:'"'select',size:44,minSize:44,maxSize:44,enableSorting:false,enableHiding:false,header:({table})=><Checkbox aria-label=\"Выделить все заказы на странице\" checked={table.getIsAllRowsSelected()} indeterminate={table.getIsSomeRowsSelected()} onChange={table.getToggleAllRowsSelectedHandler()}/>,cell:({row})=><Checkbox aria-label={"'`Выделить заказ ${row.original.id}`} checked={row.getIsSelected()} indeterminate={row.getIsSomeSelected()} onChange={row.getToggleSelectedHandler()}/>},
    {id:'"'id',accessorKey:'id',header:'Заказ',size:112,cell:({row})=><Button view=\"flat\" className=\"order-link\" onClick={()=>onDetail(row.original)}>#{row.original.id}</Button>},
    {id:'customer',accessorKey:'customer',header:'Клиент',size:264,cell:({row})=><Customer order={row.original}/>},
    {id:'date',accessorKey:'date',header:'Дата создания',size:149,cell:({row})=><div className=\"date-cell\"><span>{displayDate(row.original.date)}</span><span className=\"secondary\">{row.original.time}</span></div>},
    {id:'status',accessorKey:'status',header:'Статус',size:135,cell:({row})=><StatusBadge status={row.original.status}/>},
    {id:'amount',accessorKey:'amount',header:'Сумма',size:122,cell:({row})=><span className=\"amount\">{money(row.original.amount)}</span>},
    {id:'payment',accessorKey:'payment',header:'Оплата',size:151,cell:({row})=><span className={"'`payment payment-${row.original.payment}`}>{row.original.payment==='"'paid'?ico(CircleCheck,14):row.original.payment==='pending'?<span className=\"payment-pending-dot\"/>:ico(ArrowUpRight,14)}{row.original.payment==='paid'?'Оплачено':row.original.payment==='pending'?'Ожидает оплаты':'Возврат'}</span>},
    {id:'actions',size:46,minSize:46,maxSize:46,enableSorting:false,enableHiding:false,header:'',cell:({row})=><Button view=\"flat\" size=\"s\" aria-label={"'`Открыть заказ ${row.original.id}`} onClick={()=>onDetail(row.original)}>{ico(Ellipsis,18)}</Button>},
  ],[onDetail]);
  const table=useTable({columns,data,getRowId,getSubRows,enableRowSelection:true,enableMultiRowSelection:true,enableExpanding:true,enableSorting:true,manualSorting:true,onSortingChange:setSorting,onRowSelectionChange,onExpandedChange:setExpanded,onColumnOrderChange:setColumnOrder,onColumnVisibilityChange:setColumnVisibility,state:{rowSelection,expanded,sorting,columnOrder,columnVisibility}});
