    {grouped&&<div className="grouping-info"><span>{ico(Layers,14)}Группировка: <strong>Статус заказа</strong></span><Button size="s" view="flat" onClick={()=>table.toggleAllRowsExpanded(!table.getIsAllRowsExpanded())}>{table.getIsAllRowsExpanded()?'"'Свернуть всё':'Развернуть всё'}</Button><Button size=\"s\" view=\"flat\" aria-label=\"Убрать группировку\" onClick={()=>setGrouped(false)}>{ico(Xmark,13)}</Button></div>}
