    <div className=\"table-scroll\"><ColumnReorderingProvider table={table}><Table table={table} size=\"m\" className=\"orders-table\" headerCellClassName=\"orders-th\" cellClassName=\"orders-td\" groupHeaderClassName=\"orders-group-header\" rowClassName={row=>row?.getIsSelected()?'order-row selected-row':'order-row'} getGroupTitle={row=><span className=\"group-title\"><StatusBadge status={row.original.status}/><span className=\"group-total\">{row.subRows.length} на странице · {filtered.filter(o=>o.status===row.original.status).length} всего</span></span>} emptyContent={<div className=\"empty-state\"><span className=\"empty-icon\">{ico(Magnifier,28)}</span><Text variant=\"subheader-3\">Заказы не найдены</Text><p className=\"secondary\">Попробуйте изменить запрос или сбросить фильтры.</p><Button view=\"outlined\" onClick={reset}>Сбросить фильтры</Button><Button view=\"flat\" onClick={onCreate}>Создать заказ</Button></div>}/></ColumnReorderingProvider></div>
    <div className=\"table-pagination\"><div className=\"pagination-summary\">{filtered.length?<><strong>{(safePage-1)*pageSize+1}–{Math.min(safePage*pageSize,filtered.length)}</strong> из {filtered.length} заказов</>:'0 заказов'}{selectedIds.length>0&&<span> · Выбрано {selectedIds.length}</span>}</div><div className=\"pagination-controls\"><span className=\"secondary page-size-label\">На странице</span><Select size=\"m\" value={[String(pageSize)]} options={[8,15,25,50].map(n=>({value:String(n),content:String(n)}))} onUpdate={([n])=>setPageSize(Number(n))} aria-label=\"Заказов на странице\"/><div className=\"pagination-divider\"/><Button view=\"flat\" size=\"m\" aria-label=\"Предыдущая страница\" disabled={safePage===1} onClick={()=>setPage(safePage-1)}>{ico(ChevronLeft,14)}</Button>{Array.from({length:pages},(_,i)=>i+1).filter(p=>p===1||p===pages||Math.abs(p-safePage)<=1).map((p,i,arr)=><span className=\"page-number-wrap\" key={p}>{i>0&&p-arr[i-1]>1&&<span className=\"page-ellipsis\">…</span>}<Button view=\"flat\" size=\"m\" className={p===safePage?'current-page':''} aria-label={"'`Страница ${p}`} aria-current={p===safePage?'"'page':undefined} onClick={()=>setPage(p)}>{p}</Button></span>)}<Button view=\"flat\" size=\"m\" aria-label=\"Следующая страница\" disabled={safePage===pages} onClick={()=>setPage(safePage+1)}>{ico(ChevronRight,14)}</Button></div></div>
