  return <form className=\"create-form\" onSubmit={e=>{e.preventDefault();setSubmitted(true);if("'!name.trim()||!/''^'"\\S+@\\S+\\.\\S+"'$/.test(email)||!Number.isFinite(Number(amount))||Number(amount)<=0)return;onSave({id:nextId,customer:name.trim(),email,initials:name.trim().split(/'"\\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase(),tone:Math.floor(Number(nextId)%6),date:new Date().toISOString().slice(0,10),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),amount:Number(amount),status,payment:status==='cancelled'?'refunded':'pending',items:1});}}><p className=\"secondary\">Заполните данные клиента и сумму заказа.</p><label>Имя клиента<TextInput size=\"l\" value={name} onUpdate={setName} placeholder=\"Иван Иванов\" autoFocus validationState={submitted&&"'!name.trim()?'"'invalid':undefined} errorMessage={submitted&&"'!name.trim()?'"'Укажите имя клиента':undefined}/></label><label>Электронная почта<TextInput size=\"l\" value={email} onUpdate={setEmail} type=\"email\" placeholder=\"ivan@example.com\" validationState={submitted&&"'!/''^'"\\S+@\\S+\\.\\S+"'$/.test(email)?'"'invalid':undefined} errorMessage={submitted&&"'!/''^'"\\S+@\\S+\\.\\S+"'$/.test(email)?'"'invalid'===String('invalid')?'Введите корректный email':undefined:undefined}/></label><label>Сумма, ₽<TextInput size=\"l\" type=\"number\" value={amount} onUpdate={setAmount} placeholder=\"0\" controlProps={{min:'0.01',step:'0.01'}} validationState={submitted&&Number(amount)<=0?'invalid':undefined} errorMessage={submitted&&Number(amount)<=0?'Сумма должна быть больше нуля':undefined}/></label><label>Статус<Select size=\"l\" width=\"max\" value={[status]} onUpdate={([s])=>setStatus(s as Status)} options={statuses.map(s=>({value:s.id,content:s.label}))}/></label><div className=\"modal-actions\"><Button view=\"outlined\" size=\"l\" onClick={onCancel}>Отмена</Button><Button type=\"submit\" view=\"action\" size=\"l\">Создать заказ</Button></div></form>;
}
function Users({orders,onDetail}:{orders:Order[];onDetail:(o:Order)=>void}) {
  const [search,setSearch]=useState('');const users=useMemo(()=>Array.from(new Map(orders.map(o=>[o.email,o])).values()).filter(o=>"'`${o.customer} ${o.email}`.toLowerCase().includes(search.toLowerCase())),[orders,search]);
