import {ArrowDownToLine, ArrowUpRight, Bell, Calendar, ChevronDown, ChevronLeft, ChevronRight, CircleCheck, CircleQuestion, Clock, CreditCard, Ellipsis, Gear, House, Layers, LayoutColumns, Magnifier, Persons, Plus, ShoppingBag, Xmark} from '@gravity-ui/icons';
import {displayDate, exportOrders, initialOrders, money, Order, Status, statuses} from './data';
import './styles.css';
configure({lang: 'ru'});
const getSubRows = (o: Order) => o.children;
const getRowId = (o: Order) => o.id;
const columnIds = ['select', 'id', 'customer', 'date', 'status', 'amount', 'payment', 'actions'];
const columnNames: Record<string, string> = {id:'Заказ', customer:'Клиент', date:'Дата создания', status:'Статус', amount:'Сумма', payment:'Оплата'};
const ico = (data: typeof Plus, size = 16) => <Icon data={data} size={size}/>;
function readStored<T,>(key: string, fallback: T): T {try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback; } catch {return fallback;}}
function BrandIcon() {return <svg width=\"30\" height=\"30\" viewBox=\"0 0 30 30\" fill=\"none\"><rect width=\"30\" height=\"30\" rx=\"8\" fill=\"currentColor\"/><path d=\"M8 8H14V14H8V8ZM16 8H22V14H16V8ZM8 16H14V22H8V16ZM16 16H22V22H16V16Z\" fill=\"var(--g-color-text-brand-contrast)\"/></svg>;}
function StatusBadge({status}: {status: Status}) {return <span className={"'`status-badge status-${status}`}><span className="status-dot"/>{statuses.find(s => s.id === status)?.label}</span>;}
function Customer({order}: {order: Order}) {return <div className="customer"><span className={`initial-avatar tone-${order.tone}`}>{order.initials}</span><div className="customer-copy"><span>{order.customer}</span><span className="secondary email">{order.email}</span></div></div>;}
function Metrics({orders}: {orders: Order[]}) {
  const cards = [
    {label:'"'Всего заказов', value:String(orders.length), delta:'+12,8%', note:'за последние 30 дней', icon:ShoppingBag, tone:'purple'},
    {label:'В работе', value:String(orders.filter(o => o.status === 'processing').length), delta:'+8,2%', note:'требуют вашего внимания', icon:Clock, tone:'orange'},
    {label:'Завершённые', value:String(orders.filter(o => o.status === 'completed').length), delta:'+16,4%', note:'успешно доставлены', icon:CircleCheck, tone:'green'},
    {label:'Выручка', value:money(orders.filter(o => o.payment === 'paid').reduce((s,o) => s + o.amount,0)), delta:'+18,6%', note:'по оплаченным заказам', icon:CreditCard, tone:'blue'},
  ];
  return <div className=\"metrics\">{cards.map(c => <div className=\"metric-card\" key={c.label}><div className=\"metric-top\"><span>{c.label}</span><span className={"'`metric-icon ${c.tone}`}>{ico(c.icon,18)}</span></div><div className="metric-value">{c.value}</div><div className="metric-bottom"><span className="metric-trend">{ico(ArrowUpRight,13)}{c.delta}</span><span>{c.note}</span></div></div>)}</div>;
}
export function App() {
  const [compact, setCompact] = useState(() => readStored('"'contour-compact', window.innerWidth < 800));
  const [section, setSection] = useState('orders');
  const [orders, setOrders] = useState<Order[]>(() => readStored('contour-orders', initialOrders));
  const [modal, setModal] = useState<'create'|'help'|'notifications'|'profile'|null>(null);
  const [detail, setDetail] = useState<Order|null>(null);
  const [notice, setNotice] = useState('');
