  const title = ({home:'Главная',users:'Пользователи',orders:'Заказы',settings:'Настройки'} as Record<string,string>)[section];
  const updateStatus = (id: string, status: Status) => {setOrders(old => old.map(o => o.id === id ? {...o,status,payment:status==='cancelled'?'refunded':o.payment} : o));setDetail(null);setNotice('Статус заказа обновлён');};
  const content = <div className=\"workspace\">
    <header className=\"topbar\"><div className=\"breadcrumbs\"><span>Рабочее пространство</span>{ico(ChevronRight,12)}<span className=\"breadcrumb-current\">{title}</span></div><div className=\"topbar-right\"><span className=\"live-indicator\"><span/>Все системы работают</span><div className=\"topbar-divider\"/><Button view=\"flat\" size=\"l\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={() => setModal('notifications')}>{ico(Bell,19)}<span className=\"notification-dot\"/></Button><Button view=\"flat\" className=\"profile-button\" aria-label=\"Профиль Алексея Морозова\" onClick={() => setModal('profile')}><span className=\"profile-avatar\">АМ</span>{ico(ChevronDown,12)}</Button></div></header>
    <main className=\"main-content\"><div className=\"page-heading\"><div><div className=\"heading-line\"><Text variant=\"header-1\">{title}</Text>{section === 'orders' && <span className=\"heading-badge\">{orders.length}</span>}</div><p className=\"page-description\">{section==='orders'?'Управляйте заказами и следите за каждым этапом.':section==='home'?'Всё, что происходит в вашем магазине, — в одном месте.':section==='users'?'Ваши клиенты и история их заказов.':'Управляйте профилем и настройками рабочего пространства.'}</p></div>{(section==='orders'||section==='home') && <div className=\"page-actions\"><Button size=\"l\" view=\"outlined\" onClick={() => {exportOrders(orders);setNotice('Заказы экспортированы в CSV');}}>{ico(ArrowDownToLine)}Экспорт</Button><Button size=\"l\" view=\"action\" onClick={() => setModal('create')}>{ico(Plus,18)}Создать заказ</Button></div>}</div>
